<script setup lang="ts">
import {ref} from 'vue';
const current=ref(''),password=ref(''),confirm=ref(''),message=ref(''),error=ref(''),busy=ref(false),show=ref(false);
async function change(){message.value='';error.value='';if(password.value!==confirm.value){error.value='两次输入的新密码不一致。';return;}busy.value=true;try{const r=await fetch('/api/password',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'gradebook'},body:JSON.stringify({currentPassword:current.value,newPassword:password.value})});const body=await r.json();if(!r.ok)throw Error(body.error||'修改失败。');current.value='';password.value='';confirm.value='';message.value='密码已更新，其他设备需要重新登录。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><form class="password-settings" @submit.prevent="change"><h2>访问密码</h2><p>修改密码后，其他设备需要重新登录。</p><label>当前密码<input v-model="current" :type="show?'text':'password'" autocomplete="current-password" required></label><label>新密码<input v-model="password" :type="show?'text':'password'" autocomplete="new-password" minlength="10" maxlength="256" required></label><label>再次输入新密码<input v-model="confirm" :type="show?'text':'password'" autocomplete="new-password" minlength="10" maxlength="256" required></label><label class="password-toggle"><input v-model="show" type="checkbox"> 显示密码</label><p v-if="error" class="j-error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><button class="j-button j-primary" :disabled="busy">保存新密码</button></form></template>
